1	import { db } from "@/lib/db";
2	import type { Invoice, InvoiceStatus, User } from "@prisma/client";
3	
4	/**
5	 * Invoice line item shape stored in `Invoice.lineItems` (Json).
6	 * Amounts are integer cents. `amountCents` is authoritative; qty * unitCents
7	 * is used as a fallback when a line omits it.
8	 */
9	export type LineItem = {
10	  description: string;
11	  qty: number;
12	  unitCents: number;
13	  amountCents: number;
14	};
15	
16	export function coerceLineItems(raw: unknown): LineItem[] {
17	  if (!Array.isArray(raw)) return [];
18	  return raw
19	    .filter((x): x is Record<string, unknown> => !!x && typeof x === "object")
20	    .map((x) => {
21	      const qty = Number(x.qty ?? 1) || 0;
22	      const unitCents = Math.round(Number(x.unitCents ?? 0) || 0);
23	      const amountCents = Math.round(
24	        Number(x.amountCents ?? qty * unitCents) || 0
25	      );
26	      return {
27	        description: String(x.description ?? "Item"),
28	        qty,
29	        unitCents,
30	        amountCents,
31	      };
32	    });
33	}
34	
35	/** Compute subtotal / tax / total (all integer cents) for an invoice. */
36	export function invoiceTotals(invoice: Pick<Invoice, "lineItems" | "taxCents" | "amountCents">) {
37	  const items = coerceLineItems(invoice.lineItems);
38	  const subtotalCents = items.reduce((sum, li) => sum + li.amountCents, 0);
39	  const taxCents = invoice.taxCents ?? 0;
40	  // `amountCents` is the stored authoritative total; fall back to computed.
41	  const totalCents = invoice.amountCents ?? subtotalCents + taxCents;
42	  return { items, subtotalCents, taxCents, totalCents };
43	}
44	
45	const STATUS_LABEL: Record<InvoiceStatus, string> = {
46	  OPEN: "Open",
47	  PAID: "Paid",
48	  VOID: "Void",
49	  REFUNDED: "Refunded",
50	};
51	
52	export function invoiceStatusLabel(status: InvoiceStatus): string {
53	  return STATUS_LABEL[status] ?? status;
54	}
55	
56	/**
57	 * Create an Invoice row. The total (`amountCents`) is derived from the line
58	 * items plus tax so callers can't accidentally desync the stamped total from
59	 * the itemised breakdown.
60	 */
61	export async function createInvoice(opts: {
62	  userId: string;
63	  description: string;
64	  lineItems: LineItem[];
65	  taxCents?: number;
66	  status?: InvoiceStatus;
67	  period?: { start?: Date | null; end?: Date | null };
68	}): Promise<Invoice> {
69	  const items = opts.lineItems.map((li) => ({
70	    description: String(li.description),
71	    qty: Number(li.qty) || 0,
72	    unitCents: Math.round(Number(li.unitCents) || 0),
73	    amountCents: Math.round(
74	      Number(li.amountCents ?? (Number(li.qty) || 0) * (Number(li.unitCents) || 0)) || 0
75	    ),
76	  }));
77	  const taxCents = Math.round(opts.taxCents ?? 0);
78	  const subtotalCents = items.reduce((s, li) => s + li.amountCents, 0);
79	  const amountCents = subtotalCents + taxCents;
80	  const status = opts.status ?? "OPEN";
81	
82	  return db.invoice.create({
83	    data: {
84	      userId: opts.userId,
85	      description: opts.description,
86	      lineItems: items,
87	      taxCents,
88	      amountCents,
89	      status,
90	      paidAt: status === "PAID" ? new Date() : null,
91	      periodStart: opts.period?.start ?? null,
92	      periodEnd: opts.period?.end ?? null,
93	    },
94	  });
95	}
96	
97	function esc(s: unknown): string {
98	  return String(s ?? "")
99	    .replace(/&/g, "&amp;")
100	    .replace(/</g, "&lt;")
101	    .replace(/>/g, "&gt;")
102	    .replace(/"/g, "&quot;");
103	}
104	
105	function money(cents: number): string {
106	  const neg = cents < 0;
107	  return `${neg ? "−" : ""}$${(Math.abs(cents) / 100).toFixed(2)}`;
108	}
109	
110	function fmtDate(d: Date | null | undefined): string {
111	  if (!d) return "—";
112	  return new Date(d).toLocaleDateString("en-US", {
113	    year: "numeric",
114	    month: "short",
115	    day: "numeric",
116	  });
117	}
118	
119	const STATUS_STAMP: Record<InvoiceStatus, { color: string; label: string }> = {
120	  PAID: { color: "#10b981", label: "PAID" },
121	  OPEN: { color: "#f59e0b", label: "OPEN" },
122	  VOID: { color: "#64748b", label: "VOID" },
123	  REFUNDED: { color: "#8a70fb", label: "REFUNDED" },
124	};
