1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "@/lib/db";
5	import { requireAdmin } from "@/lib/auth";
6	import { createInvoice, type LineItem } from "@/lib/invoices";
7	
8	async function audit(userId: string | null, action: string, detail?: string) {
9	  await db.auditLog.create({ data: { userId, action, detail } });
10	}
11	
12	/**
13	 * Admin: generate an OPEN invoice for a server's current plan (one billing
14	 * period). Does not charge the wallet — it records what is owed; the wallet
15	 * ledger and invoices are complementary records.
16	 */
17	export async function generateInvoiceForServer(serverId: string) {
18	  const admin = await requireAdmin();
19	  const server = await db.server.findUnique({
20	    where: { id: serverId },
21	    include: { plan: true, user: { select: { id: true, email: true } } },
22	  });
23	  if (!server) throw new Error("Server not found");
24	  if (server.isFree) throw new Error("Free servers are not billed");
25	
26	  const now = new Date();
27	  const periodEnd = new Date(now.getTime() + 30 * 86400_000);
28	  const line: LineItem = {
29	    description: `${server.plan.name} — ${server.hostname}`,
30	    qty: 1,
31	    unitCents: server.plan.priceCents,
32	    amountCents: server.plan.priceCents,
33	  };
34	
35	  const invoice = await createInvoice({
36	    userId: server.userId,
37	    description: `${server.plan.name} plan · ${server.hostname}`,
38	    lineItems: [line],
39	    status: "OPEN",
40	    period: { start: now, end: periodEnd },
41	  });
42	
43	  await audit(
44	    admin.id,
45	    "invoice.generate",
46	    `#${invoice.number} for ${server.hostname} (${server.user.email})`
47	  );
48	  revalidatePath("/admin/invoices");
49	  revalidatePath("/dashboard/invoices");
50	  return { id: invoice.id, number: invoice.number };
51	}
52	
53	/** Admin: void an open/unpaid invoice. */
54	export async function voidInvoice(id: string) {
55	  const admin = await requireAdmin();
56	  const invoice = await db.invoice.findUnique({ where: { id } });
57	  if (!invoice) throw new Error("Invoice not found");
58	  if (invoice.status === "PAID") throw new Error("Paid invoices cannot be voided — refund instead");
59	  if (invoice.status === "VOID") return { ok: true };
60	
61	  await db.invoice.update({ where: { id }, data: { status: "VOID", paidAt: null } });
62	  await audit(admin.id, "invoice.void", `#${invoice.number}`);
63	  revalidatePath("/admin/invoices");
64	  revalidatePath(`/admin/invoices/${id}`);
65	  revalidatePath("/dashboard/invoices");
66	  return { ok: true };
67	}
68	
69	/** Admin: mark an invoice paid. */
70	export async function markInvoicePaid(id: string) {
71	  const admin = await requireAdmin();
72	  const invoice = await db.invoice.findUnique({ where: { id } });
73	  if (!invoice) throw new Error("Invoice not found");
74	  if (invoice.status === "VOID") throw new Error("Void invoices cannot be marked paid");
75	  if (invoice.status === "PAID") return { ok: true };
76	
77	  await db.invoice.update({ where: { id }, data: { status: "PAID", paidAt: new Date() } });
78	  await audit(admin.id, "invoice.mark_paid", `#${invoice.number}`);
79	  revalidatePath("/admin/invoices");
80	  revalidatePath(`/admin/invoices/${id}`);
81	  revalidatePath("/dashboard/invoices");
82	  return { ok: true };
83	}
84	
85	/**
86	 * Admin: generate OPEN invoices for every paid, active server that has no
87	 * invoice yet. Best-effort backfill — safe to run repeatedly.
88	 */
89	export async function regenerateMissingInvoices() {
90	  const admin = await requireAdmin();
91	  const servers = await db.server.findMany({
92	    where: { isFree: false, status: { not: "DELETING" } },
93	    include: { plan: true },
94	  });
95	
96	  let created = 0;
97	  for (const server of servers) {
98	    const existing = await db.invoice.count({
99	      where: {
100	        userId: server.userId,
101	        description: { contains: server.hostname },
102	        status: { not: "VOID" },
103	      },
104	    });
105	    if (existing > 0) continue;
106	    const now = new Date();
107	    await createInvoice({
108	      userId: server.userId,
109	      description: `${server.plan.name} plan · ${server.hostname}`,
110	      lineItems: [
111	        {
112	          description: `${server.plan.name} — ${server.hostname}`,
113	          qty: 1,
114	          unitCents: server.plan.priceCents,
115	          amountCents: server.plan.priceCents,
116	        },
117	      ],
118	      status: "OPEN",
119	      period: { start: now, end: new Date(now.getTime() + 30 * 86400_000) },
120	    });
121	    created++;
122	  }
123	
124	  await audit(admin.id, "invoice.regenerate_missing", `${created} created`);
125	  revalidatePath("/admin/invoices");
126	  revalidatePath("/dashboard/invoices");
127	  return { created };
128	}
