17	/** Create a Checkout session that pays for a VPS order directly (no wallet pre-fund). */
18	export async function createOrderCheckout(
19	  user: { id: string; email: string },
20	  amountCents: number,
21	  intent: OrderIntent,
22	): Promise<string | null> {
23	  if (!stripeConfigured() || amountCents <= 0) return null;
24	  const base = process.env.APP_URL ?? "http://localhost:3000";
25	  // SSH keys are long; keep them out of Stripe metadata (500-char cap) — addable after deploy.
26	  const slim: OrderIntent = { ...intent, sshPublicKey: undefined, sshKeyName: undefined };
27	  const session = await stripe().checkout.sessions.create({
28	    mode: "payment",
29	    customer_email: user.email,
30	    line_items: [
31	      {
32	        price_data: {
33	          currency: "usd",
34	          product_data: { name: `Nxeon VPS — ${intent.hostname}` },
35	          unit_amount: amountCents,
36	        },
37	        quantity: 1,
38	      },
39	    ],
40	    metadata: { nxeonUserId: user.id, nxeonOrder: JSON.stringify(slim).slice(0, 490) },
41	    success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
42	    cancel_url: `${base}/dashboard/deploy?canceled=1`,
43	  });
44	  return session.url;
