63	/**
64	 * Credit a user's wallet for a completed Checkout session, idempotently.
65	 * Called from both the success-redirect confirm route (works without HTTPS)
66	 * and the webhook (belt-and-suspenders once HTTPS is available).
67	 * Returns true if a credit was applied this call.
68	 */
69	export async function creditCheckoutSession(sessionId: string): Promise<boolean> {
70	  const session = await stripe().checkout.sessions.retrieve(sessionId);
71	  const userId = session.metadata?.nxeonUserId;
72	  const cents = session.amount_total ?? 0;
73	  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;
74	
75	  // Legacy guard: rows credited before `stripeSessionId` existed only recorded the
76	  // session id inside the description.
77	  const legacy = await db.walletTransaction.findFirst({
78	    where: { stripeSessionId: null, description: { contains: session.id } },
79	  });
80	  if (legacy) return false;
81	
82	  // Idempotency is enforced by the UNIQUE index on `stripeSessionId` — NOT by a
83	  // read-then-write check. The confirm-redirect and the webhook can arrive
84	  // concurrently (and /api/stripe/confirm is unauthenticated and replayable), so
85	  // only the database can safely decide the winner. P2002 == already credited.
86	  try {
87	    await db.$transaction([
88	      db.walletTransaction.create({
89	        data: {
90	          userId,
91	          amountCents: cents,
92	          description: `Stripe payment (${session.id})`,
93	          stripeSessionId: session.id,
94	        },
95	      }),
96	      db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
97	      db.notification.create({
98	        data: {
99	          userId,
100	          title: `Payment of $${(cents / 100).toFixed(2)} received`,
101	          href: "/dashboard/billing",
102	        },
103	      }),
104	    ]);
105	  } catch (e) {
106	    if ((e as { code?: string })?.code === "P2002") return false; // raced — already credited
107	    throw e;
108	  }
109	  // A funded wallet is the referred user's first paid action — reward both sides.
110	  try {
111	    const { maybeRewardReferral } = await import("./actions-growth");
112	    await maybeRewardReferral(userId);
113	  } catch { /* best-effort */ }
114	  try {
115	    const u = await db.user.findUnique({ where: { id: userId } });
116	    if (u) {
117	      const { sendMail, emails } = await import("./mailer");
118	      const tpl = emails.receipt(`$${(cents / 100).toFixed(2)}`, "wallet top-up");
119	      await sendMail({ to: u.email, subject: tpl.subject, html: tpl.html });
120	    }
121	  } catch { /* best-effort */ }
122	  return true;
123	}
