160	/**
161	 * Terminate servers that have been SUSPENDED (unpaid) past the termination window,
162	 * reclaiming disk + dedicated IP. Warns the customer before the final deletion.
163	 * A payment before this point unsuspends the server, so this only ever hits
164	 * genuinely abandoned accounts. Free servers are never terminated.
165	 */
166	async function terminateOverdue(now: Date) {
167	  const suspended = await db.server.findMany({
168	    where: { isFree: false, status: "SUSPENDED", expiresAt: { not: null } },
169	  });
170	  for (const server of suspended) {
171	    const terminateAt = server.expiresAt!.getTime() + (GRACE_DAYS + TERMINATE_DAYS) * DAY;
172	    const warnAt = terminateAt - WARN_BEFORE_TERMINATE_DAYS * DAY;
173	
174	    if (now.getTime() >= terminateAt) {
175	      const pending = await db.job.count({
